const j = $input.first().json;
const raw = String(j.engagement ?? '').trim().toLowerCase();
let trigger = 'manual';
if (raw) trigger = 'form';
else if (j.timestamp || j['Readable date']) trigger = 'schedule';
if (raw && !/^[a-z0-9][a-z0-9_-]{0,39}$/.test(raw)) throw new Error(`Invalid engagement name: ${raw}`);
return [{ json: { trigger, engagement: raw || null, requested_at: new Date().toISOString() } }];

const SCOPE_PY = "import ipaddress
import json
import re
import sys
from pathlib import Path

HOST_RE = re.compile(r"^(?=.{1,253}$)(?:[a-z0-9_](?:[a-z0-9_-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$")
SC = Path(__file__).resolve().parent


def lines(name: str) -> list[str]:
    p = SC / name
    if not p.exists():
        return []
    return [l.strip().lower() for l in p.read_text().splitlines() if l.strip()]


ROOTS = lines("domains.txt")
HOSTS = set(lines("hosts.txt"))
EXC_NAMES: list[str] = []
EXC_NETS: list[ipaddress.IPv4Network] = []
for e in lines("exclude.txt"):
    try:
        EXC_NETS.append(ipaddress.ip_network(e, strict=False))
    except ValueError:
        EXC_NAMES.append(e[2:] if e.startswith("*.") else e)
NETS = [ipaddress.ip_network(c, strict=False) for c in lines("cidrs.txt") + lines("ips.txt")]


def name_ok(n: str) -> str | None:
    n = n.strip().lower().rstrip(".")
    if n.startswith("*."):
        n = n[2:]
    if not HOST_RE.match(n):
        return None
    if any(n == x or n.endswith("." + x) for x in EXC_NAMES):
        return None
    if n in HOSTS or any(n == r or n.endswith("." + r) for r in ROOTS):
        return n
    return None


def ip_ok(s: str) -> str | None:
    try:
        ip = ipaddress.ip_address(s.strip())
    except ValueError:
        return None
    if ip.version != 4:
        return None
    if any(ip in n for n in EXC_NETS):
        return None
    if any(ip in n for n in NETS):
        return str(ip)
    if not ip.is_global:
        return None
    return str(ip)


def cmd_names() -> None:
    seen: set[str] = set()
    for line in sys.stdin:
        n = name_ok(line)
        if n and n not in seen:
            seen.add(n)
            print(n)


def load_nets(path: str | None) -> list[ipaddress.IPv4Network]:
    if not path or not Path(path).exists():
        return []
    out = []
    for line in Path(path).read_text().splitlines():
        try:
            out.append(ipaddress.ip_network(line.strip(), strict=False))
        except ValueError:
            continue
    return out


def load_tagged(path: str | None) -> dict[str, str]:
    if not path or not Path(path).exists():
        return {}
    out = {}
    for line in Path(path).read_text().splitlines():
        parts = line.strip().split()
        if len(parts) >= 2:
            out[parts[0]] = parts[1]
    return out


def explicit(ip: str) -> bool:
    a = ipaddress.ip_address(ip)
    return any(a in n for n in NETS)


def cmd_resolve(dnsx_path: str, extra_ips_path: str, out: str, service_nets_path: str | None = None, edge_ips_path: str | None = None) -> None:
    """Split resolved in-scope names into dedicated IPs (safe to port-scan) and shared third-party infrastructure.

    service: CNAME leaves scope, or IP is in a shared AWS service range (S3, API Gateway). No IP scans, no vuln checks.
    edge:    IP is a CDN/WAF edge (Cloudflare, CloudFront...). No IP scans; hostname still gets web checks.
    Explicitly scoped IPs/CIDRs are never dropped.
    """
    o = Path(out)
    service_nets = load_nets(service_nets_path)
    edge_ips = load_tagged(edge_ips_path)
    host_ip: dict[str, list[str]] = {}
    hosts: set[str] = set()
    shared: dict[str, str] = {}
    cname_hosts: set[str] = set()
    ips: set[str] = set()
    skipped_ips: set[str] = set()
    p = Path(dnsx_path)
    if p.exists():
        for line in p.read_text().splitlines():
            try:
                r = json.loads(line)
            except ValueError:
                continue
            h = name_ok(r.get("host", ""))
            if not h:
                continue
            chain = [c.lower().rstrip(".") for c in (r.get("cname") or [])]
            if chain:
                cname_hosts.add(h)
            resolved = sorted({i for i in (ip_ok(a) for a in r.get("a") or []) if i})
            if not resolved:
                continue
            hosts.add(h)
            ext = next((c for c in chain if not name_ok(c)), None)
            dedicated = []
            for i in resolved:
                if explicit(i):
                    dedicated.append(i)
                    continue
                a = ipaddress.ip_address(i)
                if ext:
                    shared[h] = f"service cname:{ext}"
                elif any(a in n for n in service_nets):
                    shared[h] = "service aws-shared-range"
                elif i in edge_ips:
                    shared.setdefault(h, f"edge {edge_ips[i]}")
                else:
                    dedicated.append(i)
                    continue
                skipped_ips.add(i)
            if dedicated:
                host_ip[h] = dedicated
                ips.update(dedicated)
    for src in [extra_ips_path, str(SC / "ips.txt")]:
        sp = Path(src)
        if sp.exists():
            for line in sp.read_text().splitlines():
                i = ip_ok(line)
                if i:
                    ips.add(i)
    (o / "hosts.txt").write_text("".join(f"{h}\n" for h in sorted(hosts)))
    (o / "cname_hosts.txt").write_text("".join(f"{h}\n" for h in sorted(cname_hosts)))
    (o / "ips.txt").write_text("".join(f"{i}\n" for i in sorted(ips, key=ipaddress.ip_address)))
    (o / "host_ip.json").write_text(json.dumps(host_ip))
    (o / "shared_hosts.txt").write_text("".join(f"{h}\t{why}\n" for h, why in sorted(shared.items())))
    print(json.dumps({"hosts": len(hosts), "cname_hosts": len(cname_hosts), "ips": len(ips),
                      "shared_service": sum(1 for v in shared.values() if v.startswith("service")),
                      "shared_edge": sum(1 for v in shared.values() if v.startswith("edge")),
                      "shared_ips_skipped": len(skipped_ips - ips)}))


def cmd_ipfilter() -> None:
    for line in sys.stdin:
        i = ip_ok(line)
        if i:
            print(i)


if __name__ == "__main__":
    mode = sys.argv[1]
    if mode == "names":
        cmd_names()
    elif mode == "resolve":
        cmd_resolve(*sys.argv[2:7])
    elif mode == "ips":
        cmd_ipfilter()
    else:
        sys.exit(f"unknown mode {mode}")
";
const req = $('Start Request').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.engagement);

const ENG_RE = /^[a-z0-9][a-z0-9_-]{0,39}$/;
const HOST_RE = /^(?=.{1,253}$)(?:[a-z0-9_](?:[a-z0-9_-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const IP_RE = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;
const TIME_RE = /^([01]\d|2[0-3]):([0-5]\d)$/;
const cut = (s, n = 60) => { s = String(s ?? ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const clamp = (v, lo, hi) => Math.min(Math.max(v, lo), hi);

const infer = (a) => {
  if (/^https?:///.test(a)) return 'url';
  if (a.includes('/')) return 'cidr';
  if (IP_RE.test(a)) return 'ip';
  if (a.startsWith('*.')) return 'wildcard';
  return 'domain';
};

const inWindow = (s, e) => {
  const ms = TIME_RE.exec(s ?? ''), me = TIME_RE.exec(e ?? '');
  if (!ms || !me) return true;
  const now = new Date();
  const m = now.getUTCHours() * 60 + now.getUTCMinutes();
  const a = +ms[1] * 60 + +ms[2], b = +me[1] * 60 + +me[2];
  return a <= b ? m >= a && m < b : m >= a || m < b;
};

const warnings = [];
const groups = new Map();
for (const r of rows) {
  if (r.enabled !== true) continue;
  const eng = String(r.engagement).trim().toLowerCase();
  if (!ENG_RE.test(eng)) { warnings.push(`invalid engagement name '${cut(eng)}'`); continue; }
  if (req.engagement && eng !== req.engagement) continue;
  if (!groups.has(eng)) groups.set(eng, []);
  groups.get(eng).push(r);
}

const stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d+Z$/, 'Z');
const out = [];
const skipped = [];

for (const [eng, rs] of groups) {
  const t = { domains: new Set(), hosts: new Set(), ips: new Set(), cidrs: new Set(), urls: new Set(), exclude: new Set() };
  const w = [];
  for (const r of rs) {
    const raw = String(r.asset ?? '').trim();
    const a = raw.toLowerCase();
    const type = String(r.asset_type ?? '').trim().toLowerCase() || infer(a);
    const ex = r.exclude === true;
    let ok = false;
    if (type === 'domain' || type === 'wildcard') {
      const d = a.replace(/^\*\./, '');
      if (HOST_RE.test(d)) { (ex ? t.exclude : t.domains).add(d); ok = true; }
    } else if (type === 'host') {
      if (HOST_RE.test(a)) { (ex ? t.exclude : t.hosts).add(a); ok = true; }
    } else if (type === 'ip') {
      if (IP_RE.test(a)) { (ex ? t.exclude : t.ips).add(a); ok = true; }
    } else if (type === 'cidr') {
      const m = /^(.+)/(\d{1,2})$/.exec(a);
      if (m && IP_RE.test(m[1]) && +m[2] <= 32) {
        if (ex || +m[2] >= 16) { (ex ? t.exclude : t.cidrs).add(a); ok = true; }
        else { w.push(`${a} is wider than /16, refused`); ok = true; }
      }
    } else if (type === 'url') {
      try {
        const u = new URL(raw);
        const h = u.hostname.toLowerCase();
        if (['http:', 'https:'].includes(u.protocol) && (HOST_RE.test(h) || IP_RE.test(h))) {
          if (ex) t.exclude.add(h);
          else {
            t.urls.add(u.origin + (u.pathname === '/' ? '' : u.pathname));
            (IP_RE.test(h) ? t.ips : t.hosts).add(h);
          }
          ok = true;
        }
      } catch (e) { ok = false; }
    }
    if (!ok) w.push(`ignored ${type || '?'} '${cut(raw)}'`);
  }

  const assetRows = rs.filter((r) => r.exclude !== true);
  const rates = assetRows.map((r) => parseInt(r.rate_limit, 10)).filter((n) => n > 0);
  const rate = clamp(rates.length ? Math.min(...rates) : 50, 1, 500);
  const intrusive = assetRows.length > 0 && assetRows.every((r) => r.allow_intrusive === true);
  const permute = assetRows.some((r) => r.permutations === true);
  const win = rs.find((r) => r.window_start_utc && r.window_end_utc);
  const counts = { domains: t.domains.size, hosts: t.hosts.size, ips: t.ips.size, cidrs: t.cidrs.size, urls: t.urls.size, exclude: t.exclude.size };

  if (counts.domains + counts.hosts + counts.ips + counts.cidrs === 0) { skipped.push(`${eng}: no valid targets`); continue; }
  if (win && !inWindow(win.window_start_utc, win.window_end_utc)) { skipped.push(`${eng}: outside testing window ${win.window_start_utc}-${win.window_end_utc} UTC`); continue; }

  const rand = Math.floor(Math.random() * 0x10000).toString(16).padStart(4, '0');
  const run_id = `${stamp}-${rand}`;
  const base = `/opt/loot/asm/${eng}`;
  const run_dir = `${base}/${run_id}`;
  const state_dir = `${base}/state`;
  const settings = { engagement: eng, run_id, rate, intrusive, permute, window: win ? `${win.window_start_utc}-${win.window_end_utc}` : null, counts };
  const file = (name, set) => `cat > "$R/scope/${name}" <<'ASM_EOF'
${[...set].sort().join('
')}${set.size ? '
' : ''}ASM_EOF`;
  const bundle = [
    'set -euo pipefail',
    'umask 027',
    `B='${base}'; R='${run_dir}'`,
    'mkdir -p "$B"',
    'if ! mkdir "$B/.lock" 2>/dev/null; then',
    '  if [ -n "$(find "$B/.lock" -maxdepth 0 -mmin +960 2>/dev/null)" ]; then rmdir "$B/.lock"; mkdir "$B/.lock"; else echo '{"locked":true}'; exit 0; fi',
    'fi',
    `mkdir -p "$R/scope" '${state_dir}'`,
    file('domains.txt', t.domains),
    file('hosts.txt', t.hosts),
    file('ips.txt', t.ips),
    file('cidrs.txt', t.cidrs),
    file('urls.txt', t.urls),
    file('exclude.txt', t.exclude),
    `cat > "$R/scope/scope.py" <<'ASM_PY'
${SCOPE_PY}ASM_PY`,
    `cat > "$R/scope/meta.json" <<'ASM_EOF'
${JSON.stringify(settings)}
ASM_EOF`,
    'echo '{"locked":false}''
  ].join('
') + '
';
  const bundle_b64 = Buffer.from(bundle, 'utf8').toString('base64');
  if (bundle_b64.length > 120000) { skipped.push(`${eng}: scope too large for one command (${bundle_b64.length} bytes)`); continue; }

  out.push({ json: {
    engagement: eng, run_id, run_dir, state_dir, rate,
    port_rate: clamp(rate * 10, 100, 1000), intrusive, permute,
    trigger: req.trigger, started_at: new Date().toISOString(),
    scope_counts: counts, warnings: [...warnings, ...w], bundle_b64
  } });
}

if (!out.length) {
  const why = [...skipped, ...warnings].join('; ') || (req.engagement ? `no enabled scope rows for '${req.engagement}'` : 'no enabled scope rows');
  if (req.trigger !== 'schedule') throw new Error(`Nothing to run: ${why}`);
  return [];
}
return out;

const c = $('Each Engagement').first().json;
const { bundle_b64, ...ctx } = c;
return [{ json: { ...ctx, stages: {} } }];

const ctx = $('Run Context').first().json;
const j = $input.first().json;
const ORDER = [
  ['Discovery', 'discovery'], ['Takeover Check', 'takeover'], ['Port Scan', 'ports'], ['Web Fingerprint', 'web'],
  ['Diff', 'diff'], ['Vuln Checks', 'vuln'], ['Findings & Alerts', 'findings']
];

const stages = j.stages ?? {};
const errRaw = j.error ?? null;
const failed = errRaw !== null && errRaw !== undefined;
const errMsg = failed ? String(errRaw.message ?? errRaw.description ?? errRaw).replace(/\s*\[line \d+\]$/, '').slice(0, 900) : '';
const failedStage = failed ? (ORDER.map(([, k]) => k).find((k) => !stages[k]) ?? 'unknown') : null;

const d = stages.discovery ?? {}, p = stages.ports ?? {}, w = stages.web ?? {}, df = stages.diff ?? {}, f = stages.findings ?? {}, tk = stages.takeover ?? {}, v = stages.vuln ?? {};
const started = new Date(ctx.started_at);
const finished = new Date();
const mins = Math.round((finished - started) / 60000);
const timedOut = Object.entries(stages).filter(([, s]) => s && s.timed_out).map(([k]) => k);

const notify = failed || ctx.trigger !== 'schedule' || df.baseline === true ||
  (df.assets_new ?? 0) + (df.assets_changed ?? 0) > 0 || (f.alertable ?? 0) > 0 || timedOut.length > 0;

const n = (x) => (x === undefined || x === null ? '–' : String(x));
const code = (s) => '`' + String(s).replace(/`/g, "'") + '`';
const fields = [
  { name: 'Trigger', value: ctx.trigger, inline: true },
  { name: 'Duration', value: `${mins} min`, inline: true },
  { name: 'Intrusive checks', value: ctx.intrusive ? 'on' : 'off', inline: true },
  { name: 'Names / hosts / IPs', value: `${n(d.names)} / ${n(d.hosts)} / ${n(d.ips)}`, inline: true },
  { name: 'Shared infra (no IP scans)', value: `${n(d.shared_service)} service / ${n(d.shared_edge)} edge`, inline: true },
  { name: 'Ports open (new)', value: `${n(p.ports_open)} (${n(p.ports_new)})`, inline: true },
  { name: 'Web live', value: n(w.web_live), inline: true },
  { name: 'Assets new / changed', value: `${n(df.assets_new)} / ${n(df.assets_changed)}${df.baseline ? ' · baseline' : ''}`, inline: true },
  { name: 'Takeover / vuln hits', value: `${n(tk.takeover_findings)} / ${n(v.vuln_findings)}`, inline: true },
  { name: 'New findings (alerted)', value: `${n(f.new)} (${n(f.alertable)})`, inline: true }
];
if (timedOut.length) fields.push({ name: 'Timed out (partial results)', value: timedOut.join(', ') });
if (ctx.warnings?.length) fields.push({ name: 'Scope warnings', value: ctx.warnings.slice(0, 8).join('\n').slice(0, 1024) });
if (failed) fields.push({ name: `Failed at ${failedStage}`, value: ('```\n' + errMsg + '\n```').slice(0, 1024) });
fields.push({ name: 'Evidence', value: code(ctx.run_dir) });

return [{ json: {
  run_id: ctx.run_id,
  engagement: ctx.engagement,
  status: failed ? 'failed' : 'ok',
  stage: failed ? failedStage : 'done',
  finished: finished.toISOString(),
  hosts: d.hosts ?? 0,
  assets_new: df.assets_new ?? 0,
  assets_changed: df.assets_changed ?? 0,
  findings_new: f.new ?? 0,
  error: errMsg,
  notify,
  embed: {
    title: `${failed ? '❌' : '✅'} ASM run · ${ctx.engagement}`,
    color: failed ? 0x9B111E : (f.alertable ?? 0) > 0 ? 0xE67E22 : 0x2ECC71,
    fields,
    footer: { text: `ASM · ${ctx.run_id}` },
    timestamp: finished.toISOString()
  }
} }];

const req = $('Start Request').first().json;
const day = (v) => { const d = v ? new Date(v) : null; return d && !Number.isNaN(d.getTime()) ? d.toISOString().slice(0, 10) : null; };
const key = (r) => String((r && r.engagement) || '').trim().toLowerCase();
const today = new Date().toISOString().slice(0, 10);
const by = {};
for (const i of $input.all()) {
  const r = i.json;
  if (!r || !r.engagement || r.enabled !== true) continue;
  (by[key(r)] = by[key(r)] || []).push(r);
}
const blocked = {};
for (const [e, rs] of Object.entries(by)) {
  const s = rs.map((r) => day(r.scope_start)).filter(Boolean).sort().at(-1);
  const en = rs.map((r) => day(r.scope_end)).filter(Boolean).sort()[0];
  if (s && today < s) blocked[e] = `scope starts ${s}`;
  else if (en && today > en) blocked[e] = `scope ended ${en}`;
}
const keep = $input.all().filter((i) => !blocked[key(i.json)]);
if (req.trigger !== 'schedule') {
  const live = keep.some((i) => i.json.enabled === true && (!req.engagement || key(i.json) === req.engagement));
  const hit = req.engagement ? (blocked[req.engagement] ? [req.engagement] : []) : (live ? [] : Object.keys(blocked));
  if (hit.length) throw new Error(`Nothing to run: ${hit.map((e) => `${e}: ${blocked[e]}`).join('; ')}`);
}
return keep.length ? keep : [{ json: {} }];
